--
-- Name: create_investor(text, text, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_investor(p_email text, p_password_hash text, p_full_name text, p_verification_token text DEFAULT NULL::text, p_verification_expires timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
new_id UUID;
referral_code_val TEXT;
BEGIN
referral_code_val := 'AYP-' || UPPER(SUBSTRING(MD5(RANDOM()::TEXT) FROM 1 FOR 6));
email,
password_hash,
full_name,
email_verified,
email_verification_token,
email_verification_expires,
referral_code,
created_at,
updated_at
) VALUES (
p_email,
p_password_hash,
p_full_name,
FALSE,
p_verification_token,
p_verification_expires,
referral_code_val,
NOW(),
NOW()
)
RETURNING id INTO new_id;
RETURN json_build_object(
'id', new_id,
'email', p_email,
'full_name', p_full_name,
'referral_code', referral_code_val,
'email_verified', FALSE
);
EXCEPTION
WHEN unique_violation THEN
RETURN json_build_object('error', 'Email already registered');
WHEN OTHERS THEN
RETURN json_build_object('error', SQLERRM);
END;
$$;


