--
-- Name: login_investor(text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.login_investor(p_email text, p_password text, p_remember_me boolean DEFAULT false) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
v_investor_id UUID;
v_investor_email TEXT;
v_investor_full_name TEXT;
v_investor_phone TEXT;
v_investor_company_name TEXT;
v_investor_referral_code TEXT;
v_investor_onboarding_completed BOOLEAN;
v_investor_sms_opt_in BOOLEAN;
v_investor_email_opt_in BOOLEAN;
v_investor_email_verified BOOLEAN;
v_investor_password_hash TEXT;
v_session_token TEXT;
v_session_expires TIMESTAMPTZ;
v_password_valid BOOLEAN := false;
BEGIN
IF p_email IS NULL OR p_email = '' THEN
RETURN json_build_object('success', false, 'error', 'Email is required');
END IF;
IF p_password IS NULL OR p_password = '' THEN
RETURN json_build_object('success', false, 'error', 'Password is required');
END IF;
SELECT
id, email, full_name, phone, company_name, referral_code,
onboarding_completed, sms_opt_in, email_opt_in, email_verified, password_hash
INTO
v_investor_id, v_investor_email, v_investor_full_name, v_investor_phone,
v_investor_company_name, v_investor_referral_code, v_investor_onboarding_completed,
v_investor_sms_opt_in, v_investor_email_opt_in, v_investor_email_verified, v_investor_password_hash
FROM investors
WHERE LOWER(email) = LOWER(TRIM(p_email));
IF v_investor_id IS NULL THEN
RETURN json_build_object('success', false, 'error', 'Invalid email or password');
END IF;
IF v_investor_password_hash = p_password THEN
v_password_valid := true;
END IF;
IF NOT v_password_valid THEN
RETURN json_build_object('success', false, 'error', 'Invalid email or password');
END IF;
v_session_token := gen_random_uuid()::TEXT || '-' || gen_random_uuid()::TEXT;
IF p_remember_me THEN
v_session_expires := NOW() + INTERVAL '30 days';
ELSE
v_session_expires := NOW() + INTERVAL '24 hours';
END IF;
investor_id,
session_token,
is_active,
remember_me,
expires_at,
created_at
)
VALUES (
v_investor_id,
v_session_token,
true,
COALESCE(p_remember_me, false),
v_session_expires,
NOW()
);
UPDATE investors
SET last_login = NOW()
WHERE id = v_investor_id;
RETURN json_build_object(
'success', true,
'investor', json_build_object(
'id', v_investor_id,
'email', v_investor_email,
'full_name', v_investor_full_name,
'phone', v_investor_phone,
'company_name', v_investor_company_name,
'referral_code', v_investor_referral_code,
'onboarding_completed', COALESCE(v_investor_onboarding_completed, false),
'sms_opt_in', COALESCE(v_investor_sms_opt_in, false),
'email_opt_in', COALESCE(v_investor_email_opt_in, true)
),
'session', json_build_object(
'token', v_session_token,
'expires_at', v_session_expires
),
'email_verified', COALESCE(v_investor_email_verified, false)
);
EXCEPTION
WHEN OTHERS THEN
RETURN json_build_object('success', false, 'error', 'Login failed: ' || SQLERRM);
END;
$$;


--
-- Name: realtime_notify_deal_flow_notifications(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.realtime_notify_deal_flow_notifications() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
    DECLARE
      payload jsonb;
      payload_text text;
    BEGIN
      payload := jsonb_build_object(
        'type', TG_OP,
        'schema', 'public',
        'table', TG_TABLE_NAME,
        'record', CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN row_to_json(NEW)::jsonb ELSE NULL END,
        'old_record', CASE WHEN TG_OP IN ('UPDATE', 'DELETE') THEN row_to_json(OLD)::jsonb ELSE NULL END,
        'commit_timestamp', now()::text
      );
      payload_text := payload::text;
      -- pg_notify has an 8000-byte limit; truncate large payloads to avoid
      -- breaking the user's INSERT/UPDATE/DELETE with "payload string too long"
      IF length(payload_text) > 7500 THEN
        payload := jsonb_build_object(
          'type', TG_OP,
          'schema', 'public',
          'table', TG_TABLE_NAME,
          'record', CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN jsonb_build_object('id', NEW.id) ELSE NULL END,
          'old_record', CASE WHEN TG_OP IN ('UPDATE', 'DELETE') THEN jsonb_build_object('id', OLD.id) ELSE NULL END,
          'commit_timestamp', now()::text,
          'truncated', true
        );
        payload_text := payload::text;
      END IF;
      BEGIN
        PERFORM pg_notify('realtime:zhobqrmkbtsqugtiahyn:public:deal_flow_notifications', payload_text);
      EXCEPTION WHEN OTHERS THEN
        -- Never let notification failures break user DML operations
        NULL;
      END;
      RETURN COALESCE(NEW, OLD);
    END;
    $$;


