--
-- Name: register_investor(text, text, text, text, boolean, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.register_investor(p_email text, p_password text, p_full_name text, p_phone text DEFAULT NULL::text, p_sms_opt_in boolean DEFAULT false, p_email_opt_in boolean DEFAULT true, p_referral_code text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
v_investor_id UUID;
v_ref_code TEXT;
v_session_token TEXT;
v_session_expires TIMESTAMPTZ;
v_existing_count INTEGER;
BEGIN
IF p_email IS NULL OR p_email = '' THEN
RETURN json_build_object('success', false, 'error', 'Email is required');
END IF;
IF p_password IS NULL OR p_password = '' THEN
RETURN json_build_object('success', false, 'error', 'Password is required');
END IF;
IF p_full_name IS NULL OR p_full_name = '' THEN
RETURN json_build_object('success', false, 'error', 'Full name is required');
END IF;
SELECT COUNT(*) INTO v_existing_count
FROM investors
WHERE LOWER(email) = LOWER(TRIM(p_email));
IF v_existing_count > 0 THEN
RETURN json_build_object('success', false, 'error', 'An account with this email already exists');
END IF;
v_ref_code := 'AYP' || UPPER(SUBSTRING(MD5(RANDOM()::TEXT || NOW()::TEXT) FROM 1 FOR 6));
WHILE EXISTS (SELECT 1 FROM investors WHERE referral_code = v_ref_code) LOOP
v_ref_code := 'AYP' || UPPER(SUBSTRING(MD5(RANDOM()::TEXT || NOW()::TEXT) FROM 1 FOR 6));
END LOOP;
email,
password_hash,
full_name,
phone,
sms_opt_in,
email_opt_in,
referred_by,
referral_code,
onboarding_completed,
email_verified,
created_at
)
VALUES (
LOWER(TRIM(p_email)),
p_password,
TRIM(p_full_name),
NULLIF(TRIM(p_phone), ''),
COALESCE(p_sms_opt_in, false),
COALESCE(p_email_opt_in, true),
NULLIF(TRIM(p_referral_code), ''),
v_ref_code,
false,
false,
NOW()
)
RETURNING id INTO v_investor_id;
v_session_token := gen_random_uuid()::TEXT || '-' || gen_random_uuid()::TEXT;
v_session_expires := NOW() + INTERVAL '24 hours';
investor_id,
session_token,
is_active,
expires_at,
created_at
)
VALUES (
v_investor_id,
v_session_token,
true,
v_session_expires,
NOW()
);
RETURN json_build_object(
'success', true,
'investor', json_build_object(
'id', v_investor_id,
'email', LOWER(TRIM(p_email)),
'full_name', TRIM(p_full_name),
'referral_code', v_ref_code,
'onboarding_completed', false
),
'session', json_build_object(
'token', v_session_token,
'expires_at', v_session_expires
),
'email_verified', false,
'message', 'Account created successfully!'
);
EXCEPTION
WHEN unique_violation THEN
RETURN json_build_object('success', false, 'error', 'An account with this email already exists');
WHEN OTHERS THEN
RETURN json_build_object('success', false, 'error', 'Registration failed: ' || SQLERRM);
END;
$$;


--
-- Name: sync_investor_portfolio_counts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_investor_portfolio_counts() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
affected_investor_id uuid;
prop_count integer;
monthly_rev numeric;
BEGIN
IF TG_OP = 'DELETE' THEN
affected_investor_id := OLD.investor_id;
ELSIF TG_OP = 'UPDATE' AND OLD.investor_id IS DISTINCT FROM NEW.investor_id THEN
SELECT COUNT(*), COALESCE(SUM(COALESCE(monthly_earnings, monthly_rent, 0)), 0)
INTO prop_count, monthly_rev
FROM investor_portfolio
WHERE investor_id = OLD.investor_id AND status = 'active';
UPDATE investors
SET portfolio_count = prop_count,
portfolio_monthly_revenue = monthly_rev,
updated_at = NOW()
WHERE id = OLD.investor_id;
affected_investor_id := NEW.investor_id;
ELSE
affected_investor_id := COALESCE(NEW.investor_id, OLD.investor_id);
END IF;
SELECT COUNT(*), COALESCE(SUM(COALESCE(monthly_earnings, monthly_rent, 0)), 0)
INTO prop_count, monthly_rev
FROM investor_portfolio
WHERE investor_id = affected_investor_id AND status = 'active';
UPDATE investors
SET portfolio_count = prop_count,
portfolio_monthly_revenue = monthly_rev,
updated_at = NOW()
WHERE id = affected_investor_id;
RETURN COALESCE(NEW, OLD);
END;
$$;


