--
-- Name: validate_investor_session(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_investor_session(p_session_token text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
v_session_id UUID;
v_session_expires TIMESTAMPTZ;
v_session_investor_id UUID;
v_investor_id UUID;
v_investor_email TEXT;
v_investor_full_name TEXT;
v_investor_referral_code TEXT;
v_investor_onboarding_completed BOOLEAN;
BEGIN
IF p_session_token IS NULL OR p_session_token = '' THEN
RETURN json_build_object('success', false, 'error', 'No session token provided');
END IF;
SELECT id, expires_at, investor_id
INTO v_session_id, v_session_expires, v_session_investor_id
FROM investor_sessions
WHERE session_token = p_session_token
AND is_active = true;
IF v_session_id IS NULL THEN
RETURN json_build_object('success', false, 'error', 'Invalid session');
END IF;
IF v_session_expires < NOW() THEN
UPDATE investor_sessions SET is_active = false WHERE id = v_session_id;
RETURN json_build_object('success', false, 'error', 'Session expired');
END IF;
SELECT id, email, full_name, referral_code, onboarding_completed
INTO v_investor_id, v_investor_email, v_investor_full_name, v_investor_referral_code, v_investor_onboarding_completed
FROM investors
WHERE id = v_session_investor_id;
IF v_investor_id IS NULL THEN
RETURN json_build_object('success', false, 'error', 'Investor not found');
END IF;
RETURN json_build_object(
'success', true,
'investor', json_build_object(
'id', v_investor_id,
'email', v_investor_email,
'full_name', v_investor_full_name,
'referral_code', v_investor_referral_code,
'onboarding_completed', COALESCE(v_investor_onboarding_completed, false)
),
'session', json_build_object(
'token', p_session_token,
'expires_at', v_session_expires
)
);
EXCEPTION
WHEN OTHERS THEN
RETURN json_build_object('success', false, 'error', 'Session validation failed: ' || SQLERRM);
END;
$$;


--
-- Name: auth_uid(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.auth_uid() RETURNS uuid
    LANGUAGE sql
    AS $$
  SELECT current_setting('request.jwt.claim.sub', true)::uuid
$$;


--
-- Name: role(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.role() RETURNS text
    LANGUAGE sql
    AS $$
  SELECT COALESCE(current_setting('request.jwt.claim.role', true), 'anon')
$$;


--
-- Name: foldername(text); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.foldername(name text) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT string_to_array(name, '/')
$$;


