-- Grant SELECT/INSERT/UPDATE/DELETE on all public tables to service_role
DO $$
DECLARE
  r RECORD;
BEGIN
  FOR r IN SELECT tablename FROM pg_tables WHERE schemaname = 'public' LOOP
    EXECUTE 'GRANT ALL ON TABLE public.' || quote_ident(r.tablename) || ' TO service_role';
    EXECUTE 'GRANT SELECT ON TABLE public.' || quote_ident(r.tablename) || ' TO anon';
    EXECUTE 'GRANT ALL ON TABLE public.' || quote_ident(r.tablename) || ' TO authenticated';
  END LOOP;
END $$;

-- Grant on sequences
DO $$
DECLARE
  r RECORD;
BEGIN
  FOR r IN SELECT sequencename FROM pg_sequences WHERE schemaname = 'public' LOOP
    EXECUTE 'GRANT USAGE, SELECT ON SEQUENCE public.' || quote_ident(r.sequencename) || ' TO anon, authenticated, service_role';
  END LOOP;
END $$;

-- Enable Row Level Security bypass for service_role
ALTER ROLE service_role BYPASSRLS;

